contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint addAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= addAmount, "insufficient balance for add");

        c.addToBalance{value: addAmount}();

        uint balBefore = c.getBalance(address(this));
        require(balBefore >= withdrawAmount, "withdrawAmount exceeds recorded balance");

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.getBalance(address(this));

        assert(!reverted && balAfter == balBefore - withdrawAmount);
    }

    receive() external payable {}
}

