contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address u, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(!_isContract(u));

        uint before = c.getBalance(u);
        uint cBalBefore = address(c).balance;

        c.addToBalance{value: amount}();

        uint after_ = c.getBalance(u);
        uint cBalAfter = address(c).balance;

        assert(after_ == before + amount && cBalAfter == cBalBefore + amount && c.getBalance(u) <= address(c).balance);
    }

    receive() external payable {}

    function _isContract(address a) internal view returns (bool) {
        uint32 s;
        assembly { s := extcodesize(a) }
        return s > 0;
    }
}

